insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-01', 1, 'choice', 'Situaciones', $j${"title": "¿Qué dices?", "es": "Son las 8 de la noche. Llegas a la recepción de un hotel.", "options": ["Bonsoir !", "Bonne nuit !", "Bonne journée !", "Salut !"], "answer": 0, "two": true, "explain": "<b>Bonsoir</b> sirve para saludar por la noche. <b>Bonne nuit</b> se dice al despedirse, antes de dormir, y <b>Salut</b> es solo para amigos."}$j$, 'draft'),
  ('a1-01', 2, 'type', 'Vocabulario', $j${"title": "Completa la despedida", "before": "Au", "after": ", bonne journée !", "answers": ["revoir"], "explain": "<b>Au revoir</b> = adiós. Es neutro: sirve con todo el mundo, en el trabajo y con amigos."}$j$, 'draft'),
  ('a1-01', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha el diálogo", "audio": "Bonjour Madame Diaz, comment allez-vous ? — Très bien, merci. Et vous ? — Bien, merci. Au revoir, bonne journée !", "question": "¿Cómo es esta conversación?", "options": ["Amistosa (tu)", "Por la noche", "Formal (vous)", "Muy familiar"], "answer": 2, "two": true, "explain": "Usan <b>Madame</b> y <b>Comment allez-vous ?</b>: es una conversación formal, con <b>vous</b>."}$j$, 'draft'),
  ('a1-01', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "Buenos días, señor, ¿cómo está usted?", "tiles": ["allez-vous ?", "Monsieur,", "Salut", "comment", "Bonjour", "vas"], "answer": ["Bonjour", "Monsieur,", "comment", "allez-vous ?"], "explain": "Con <b>vous</b> (formal) se pregunta <b>Comment allez-vous ?</b> <b>Salut</b> es amistoso: no va con Monsieur."}$j$, 'draft'),
  ('a1-01', 5, 'match', 'Vocabulario', $j${"title": "Une cada expresión con su traducción", "pairs": [["Bonjour", "Buenos días"], ["Bonsoir", "Buenas noches (al llegar)"], ["Bonne nuit", "Buenas noches (al dormir)"], ["Au revoir", "Adiós"], ["À demain", "Hasta mañana"], ["À bientôt", "Hasta pronto"]], "explain": "Para saludar: bonjour, bonsoir. Para despedirse: au revoir, à demain, à bientôt, bonne nuit."}$j$, 'draft'),
  ('a1-01', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Au revoir Madame, bonne journée !", "answers": ["Au revoir Madame, bonne journée !"], "es": "Adiós, señora, ¡buen día!", "explain": "<b>bonne</b> lleva doble n y e final porque <b>journée</b> es femenino."}$j$, 'draft'),
  ('a1-01', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Au", "revoir", "Monsieur,", "bon", "journée."], "wrong": 3, "fix": "bonne", "explain": "<b>journée</b> es femenino: se dice <b>bonne</b> journée. Igual: bonne nuit, bonne soirée."}$j$, 'draft'),
  ('a1-01', 8, 'choice', 'Vocabulario', $j${"title": "¿Cuál de estas frases es una despedida?", "options": ["Bonjour !", "Ça va ?", "Comment allez-vous ?", "À bientôt !"], "answer": 3, "two": true, "explain": "<b>À bientôt</b> = hasta pronto: sirve para irse. Las otras frases sirven para saludar."}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-02', 1, 'choice', 'Gramática', $j${"title": "Completa la frase", "fr": "___ ville est Lima.", "es": "Mi ciudad es Lima.", "options": ["Mon", "Mes", "Ma", "Moi"], "answer": 2, "two": true, "explain": "<b>ville</b> es femenino: <b>ma</b> ville. Con una palabra masculina se usa <b>mon</b>: mon nom, mon pays."}$j$, 'draft'),
  ('a1-02', 2, 'type', 'Gramática', $j${"title": "Completa la frase negativa", "before": "Je", "after": "parle pas anglais.", "answers": ["ne"], "explain": "La negación rodea el verbo: <b>ne</b> + verbo + <b>pas</b>. Je <b>ne</b> parle <b>pas</b> anglais."}$j$, 'draft'),
  ('a1-02', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha a Sofía", "audio": "Bonjour ! Mon nom est Ruiz, mon prénom est Sofia. Mon pays est la Colombie et ma ville est Cali. Je ne parle pas anglais. Je parle espagnol et un peu français.", "question": "¿Qué idioma NO habla Sofía?", "options": ["Español", "Inglés", "Francés", "Italiano"], "answer": 1, "two": true, "explain": "« Je <b>ne</b> parle <b>pas</b> anglais. » → no habla inglés."}$j$, 'draft'),
  ('a1-02', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "No vivo en París.", "tiles": ["pas", "Paris.", "ne", "à", "n’habite", "Je", "habite"], "answer": ["Je", "n’habite", "pas", "à", "Paris."], "explain": "Delante de vocal o h muda, <b>ne</b> se convierte en <b>n’</b>: je <b>n’</b>habite <b>pas</b>."}$j$, 'draft'),
  ('a1-02', 5, 'match', 'Vocabulario', $j${"title": "Une cada palabra con su traducción", "pairs": [["le nom", "el apellido"], ["le prénom", "el nombre"], ["l’âge", "la edad"], ["la ville", "la ciudad"], ["le pays", "el país"], ["la nationalité", "la nacionalidad"]], "explain": "En un formulario, <b>nom</b> = apellido y <b>prénom</b> = nombre."}$j$, 'draft'),
  ('a1-02', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Je ne parle pas anglais.", "answers": ["Je ne parle pas anglais."], "es": "No hablo inglés.", "explain": "Negación: <b>ne</b> + verbo + <b>pas</b>."}$j$, 'draft'),
  ('a1-02', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Bonjour,", "ma", "nom", "est", "Garcia."], "wrong": 1, "fix": "mon", "explain": "<b>nom</b> es masculino: <b>mon</b> nom. Igual: mon prénom, mon pays."}$j$, 'draft'),
  ('a1-02', 8, 'choice', 'Gramática', $j${"title": "¿Qué frase es correcta?", "options": ["Je parle ne pas anglais.", "Je ne parle anglais pas.", "Ne je parle pas anglais.", "Je ne parle pas anglais."], "answer": 3, "two": true, "explain": "Orden: sujeto + <b>ne</b> + verbo + <b>pas</b> + complemento."}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-03', 1, 'choice', 'Gramática', $j${"title": "Completa la pregunta", "fr": "___ est ta nationalité ?", "es": "¿Cuál es tu nacionalidad?", "options": ["Quelle", "Quel", "Comment", "Quels"], "answer": 0, "two": true, "explain": "<b>nationalité</b> es femenino: <b>quelle</b>. Con una palabra masculina: quel (quel âge, quel pays)."}$j$, 'draft'),
  ('a1-03', 2, 'type', 'Gramática', $j${"title": "Completa con quel o quelle", "before": "Bonjour !", "after": "est ton prénom ?", "answers": ["quel"], "explain": "<b>prénom</b> es masculino (ton prénom): <b>Quel</b> est ton prénom ?"}$j$, 'draft'),
  ('a1-03', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha el diálogo", "audio": "— Comment tu t’appelles ? — Je m’appelle Karim. — Quel est ton âge ? — J’ai trente-deux ans. — Quelle est ta ville ? — C’est Gatineau.", "question": "¿Cuántos años tiene Karim?", "options": ["22 años", "23 años", "42 años", "32 años"], "answer": 3, "two": true, "explain": "« J’ai <b>trente-deux</b> ans. » → 32 años."}$j$, 'draft'),
  ('a1-03', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "¿Cuál es tu ciudad?", "tiles": ["ville ?", "Quel", "est", "ton", "Quelle", "ta"], "answer": ["Quelle", "est", "ta", "ville ?"], "explain": "<b>ville</b> es femenino: <b>quelle</b> y <b>ta</b>. Quelle est ta ville ?"}$j$, 'draft'),
  ('a1-03', 5, 'match', 'Situaciones', $j${"title": "Une cada pregunta con su respuesta", "pairs": [["Comment tu t’appelles ?", "Je m’appelle Léa."], ["Quel est ton âge ?", "J’ai 30 ans."], ["Quelle est ta ville ?", "C’est Montréal."], ["Quelle est ta nationalité ?", "Je suis mexicaine."], ["Comment ça va ?", "Très bien, merci."]], "explain": "Para responder, se da la información: el nombre, la edad, la ciudad…"}$j$, 'draft'),
  ('a1-03', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Quel est ton prénom ?", "answers": ["Quel est ton prénom ?"], "es": "¿Cuál es tu nombre?", "explain": "<b>prénom</b> es masculino: <b>quel</b>, sin e final."}$j$, 'draft'),
  ('a1-03', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Bonjour,", "quel", "est", "ta", "ville ?"], "wrong": 1, "fix": "quelle", "explain": "<b>ville</b> es femenino: <b>quelle</b> est ta ville ? (ta ville → quelle)."}$j$, 'draft'),
  ('a1-03', 8, 'choice', 'Situaciones', $j${"title": "Quieres saber la edad de una persona. ¿Qué preguntas?", "options": ["Quelle est ta ville ?", "Quel est ton âge ?", "Comment tu t’appelles ?", "Quel est ton pays ?"], "answer": 1, "two": true, "explain": "<b>l’âge</b> = la edad. Es masculino: <b>quel</b> est ton âge ?"}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-04', 1, 'choice', 'Conjugación', $j${"title": "Completa la frase", "fr": "Nous ___ amis.", "es": "Somos amigos.", "options": ["sommes", "avons", "êtes", "sont"], "answer": 0, "two": true, "explain": "être con <b>nous</b>: nous <b>sommes</b>."}$j$, 'draft'),
  ('a1-04', 2, 'type', 'Conjugación', $j${"title": "Escribe el verbo conjugado", "before": "Elle", "after": "trente ans.", "hint": "avoir", "answers": ["a"], "explain": "La edad se dice con <b>avoir</b>: elle <b>a</b> trente ans (nunca con être)."}$j$, 'draft'),
  ('a1-04', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha a Daniel", "audio": "Bonjour, je suis Daniel. Je suis chilien et j’ai trente ans. J’ai deux sœurs. Je ne suis pas marié.", "question": "¿Cuántas hermanas tiene Daniel?", "options": ["Una", "Ninguna", "Dos", "Tres"], "answer": 2, "two": true, "explain": "« J’ai <b>deux</b> sœurs. » → tiene dos hermanas."}$j$, 'draft'),
  ('a1-04', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "Tengo 25 años.", "tiles": ["suis", "ans.", "Je", "25", "J’ai"], "answer": ["J’ai", "25", "ans."], "explain": "La edad va con <b>avoir</b>: <b>j’ai</b> 25 ans. «Je suis 25 ans» es un error frecuente."}$j$, 'draft'),
  ('a1-04', 5, 'match', 'Conjugación', $j${"title": "Une cada pronombre con su forma de «avoir»", "pairs": [["j’", "ai"], ["tu", "as"], ["il", "a"], ["nous", "avons"], ["vous", "avez"], ["ils", "ont"]], "explain": "avoir es irregular: ai, as, a, avons, avez, ont."}$j$, 'draft'),
  ('a1-04', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Nous sommes à Montréal.", "answers": ["Nous sommes à Montréal."], "es": "Estamos en Montreal.", "explain": "être con <b>nous</b>: nous <b>sommes</b>."}$j$, 'draft'),
  ('a1-04', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Mon", "frère", "est", "trente", "ans."], "wrong": 2, "fix": "a", "explain": "La edad se dice con <b>avoir</b>: mon frère <b>a</b> trente ans."}$j$, 'draft'),
  ('a1-04', 8, 'choice', 'Gramática', $j${"title": "¿Qué frase es correcta?", "options": ["Je suis 20 ans.", "J’ai mexicain.", "Je ai un frère.", "Je suis mexicain."], "answer": 3, "two": true, "explain": "La nacionalidad va con <b>être</b>: je suis mexicain. La edad va con avoir, y delante de vocal: <b>j’</b>ai."}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-05', 1, 'choice', 'Conjugación', $j${"title": "Completa la frase", "fr": "Ils ___ dans un restaurant.", "es": "Trabajan en un restaurante.", "options": ["travaille", "travaillons", "travaillez", "travaillent"], "answer": 3, "two": true, "explain": "Con <b>ils / elles</b>, la terminación es <b>-ent</b> (no se pronuncia): ils travaill<b>ent</b>."}$j$, 'draft'),
  ('a1-05', 2, 'type', 'Conjugación', $j${"title": "Escribe el verbo conjugado", "before": "Nous", "after": "à midi.", "hint": "manger", "answers": ["mangeons"], "explain": "Con <b>nous</b>, manger conserva la e: nous mang<b>e</b>ons (nunca «mangons»)."}$j$, 'draft'),
  ('a1-05', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha a Lucía", "audio": "Je m’appelle Lucía. J’habite à Laval. Je travaille dans un magasin. Le soir, j’étudie le français et j’écoute de la musique.", "question": "¿Qué hace Lucía por la noche?", "options": ["Estudia francés", "Trabaja en una tienda", "Mira la tele", "Come con amigos"], "answer": 0, "two": true, "explain": "« Le soir, j’<b>étudie</b> le français. »"}$j$, 'draft'),
  ('a1-05', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "Vivimos en Montreal.", "tiles": ["habitez", "Montréal.", "à", "Nous", "habitons", "en"], "answer": ["Nous", "habitons", "à", "Montréal."], "explain": "Con <b>nous</b>: habit<b>ons</b>. Con una ciudad se usa <b>à</b>: à Montréal."}$j$, 'draft'),
  ('a1-05', 5, 'match', 'Vocabulario', $j${"title": "Une cada verbo con su traducción", "pairs": [["habiter", "vivir"], ["parler", "hablar"], ["travailler", "trabajar"], ["écouter", "escuchar"], ["regarder", "mirar"], ["étudier", "estudiar"]], "explain": "Todos terminan en <b>-er</b> y se conjugan igual: -e, -es, -e, -ons, -ez, -ent."}$j$, 'draft'),
  ('a1-05', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Tu parles espagnol ?", "answers": ["Tu parles espagnol ?"], "es": "¿Hablas español?", "explain": "Con <b>tu</b>, la terminación es <b>-es</b>: tu parl<b>es</b>. La s no se pronuncia."}$j$, 'draft'),
  ('a1-05', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Ils", "parle", "français", "au", "travail."], "wrong": 1, "fix": "parlent", "explain": "Con <b>ils</b>, la terminación es <b>-ent</b>: ils parl<b>ent</b>."}$j$, 'draft'),
  ('a1-05', 8, 'choice', 'Gramática', $j${"title": "¿Qué frase es correcta?", "options": ["Je écoute la radio.", "J’écoutes la radio.", "J’écoute la radio.", "Je écouter la radio."], "answer": 2, "two": true, "explain": "Delante de vocal, <b>je</b> se convierte en <b>j’</b>. Con je, la terminación es <b>-e</b>: j’écout<b>e</b>."}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-06', 1, 'choice', 'Vocabulario', $j${"title": "¿Cómo se dice 70 en francés?", "options": ["soixante-dix", "soixante", "sept-dix", "quatre-vingts"], "answer": 0, "two": true, "explain": "70 = 60 + 10: <b>soixante-dix</b>. 80 = 4 × 20: quatre-vingts."}$j$, 'draft'),
  ('a1-06', 2, 'type', 'Vocabulario', $j${"title": "Escribe 21 en letras", "before": "Mon frère a", "after": "ans.", "answers": ["vingt et un", "vingt-et-un"], "explain": "21 = <b>vingt et un</b>, con «et». Pero 22 = vingt-deux, con guion."}$j$, 'draft'),
  ('a1-06', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha a Paulo", "audio": "Je m’appelle Paulo. J’ai quarante-deux ans. J’ai deux enfants : ils ont six et neuf ans.", "question": "¿Cuántos años tiene Paulo?", "options": ["24 años", "32 años", "42 años", "52 años"], "answer": 2, "two": true, "explain": "« J’ai <b>quarante-deux</b> ans. » → 42 años."}$j$, 'draft'),
  ('a1-06', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "Mi hermana tiene 18 años.", "tiles": ["dix-huit", "est", "ans.", "Ma", "a", "sœur", "dix-sept"], "answer": ["Ma", "sœur", "a", "dix-huit", "ans."], "explain": "La edad va con <b>avoir</b>: elle <b>a</b> 18 ans. 18 = <b>dix-huit</b> (10 + 8)."}$j$, 'draft'),
  ('a1-06', 5, 'match', 'Vocabulario', $j${"title": "Une cada número con su nombre", "pairs": [["15", "quinze"], ["16", "seize"], ["60", "soixante"], ["70", "soixante-dix"], ["80", "quatre-vingts"], ["90", "quatre-vingt-dix"]], "explain": "70 = soixante-dix, 80 = quatre-vingts, 90 = quatre-vingt-dix."}$j$, 'draft'),
  ('a1-06', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "J’ai vingt-cinq ans.", "answers": ["J’ai vingt-cinq ans.", "J’ai 25 ans."], "es": "Tengo 25 años.", "explain": "25 = <b>vingt-cinq</b>, con guion. También puedes escribir la cifra: 25."}$j$, 'draft'),
  ('a1-06', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Ma", "grand-mère", "a", "quatre-vingt", "ans."], "wrong": 3, "fix": "quatre-vingts", "explain": "80 = <b>quatre-vingts</b>, con s. La s desaparece si sigue otro número: quatre-vingt-un."}$j$, 'draft'),
  ('a1-06', 8, 'choice', 'Vocabulario', $j${"title": "¿Cómo se dice 71?", "options": ["soixante-dix-un", "soixante et onze", "soixante-onze", "soixante-et-un"], "answer": 1, "two": true, "explain": "71 = 60 + 11: <b>soixante et onze</b>. Después: soixante-douze (72), soixante-treize (73)…"}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-07', 1, 'choice', 'Vocabulario', $j${"title": "Completa la frase", "fr": "Aujourd’hui, c’est lundi. Demain, c’est ___.", "es": "Hoy es lunes. Mañana es…", "options": ["dimanche", "mercredi", "jeudi", "mardi"], "answer": 3, "two": true, "explain": "lundi → <b>mardi</b> → mercredi → jeudi → vendredi → samedi → dimanche."}$j$, 'draft'),
  ('a1-07', 2, 'type', 'Vocabulario', $j${"title": "Escribe el mes que sigue", "before": "Après juillet, c’est", "after": ".", "answers": ["août"], "explain": "juillet (julio) → <b>août</b> (agosto). Ojo: août lleva acento circunflejo en la u."}$j$, 'draft'),
  ('a1-07', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha a Inès", "audio": "Je m’appelle Inès. Mon anniversaire est en octobre. Je travaille du lundi au vendredi. Le dimanche, je regarde un film.", "question": "¿En qué mes es su cumpleaños?", "options": ["En agosto", "En octubre", "En diciembre", "En abril"], "answer": 1, "two": true, "explain": "« Mon anniversaire est en <b>octobre</b>. »"}$j$, 'draft'),
  ('a1-07', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "Mi cumpleaños es en mayo.", "tiles": ["mai.", "est", "Ma", "en", "anniversaire", "Mon", "au"], "answer": ["Mon", "anniversaire", "est", "en", "mai."], "explain": "<b>en</b> + mes: en mai, en août. <b>anniversaire</b> es masculino: mon anniversaire."}$j$, 'draft'),
  ('a1-07', 5, 'match', 'Vocabulario', $j${"title": "Une cada día con su traducción", "pairs": [["lundi", "lunes"], ["mardi", "martes"], ["mercredi", "miércoles"], ["jeudi", "jueves"], ["vendredi", "viernes"], ["samedi", "sábado"], ["dimanche", "domingo"]], "explain": "Los días se escriben con minúscula, como en español."}$j$, 'draft'),
  ('a1-07', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Le week-end, c’est samedi et dimanche.", "answers": ["Le week-end, c’est samedi et dimanche."], "es": "El fin de semana es sábado y domingo.", "explain": "<b>week-end</b> lleva guion. Los días van en minúscula."}$j$, 'draft'),
  ('a1-07', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Mon", "anniversaire", "est", "à", "septembre."], "wrong": 3, "fix": "en", "explain": "Con los meses se usa <b>en</b>: en septembre, en mai."}$j$, 'draft'),
  ('a1-07', 8, 'choice', 'Gramática', $j${"title": "¿Qué frase es correcta?", "options": ["Nous sommes en Janvier.", "Nous sommes à janvier.", "Nous sommes en janvier.", "Nous sommes au janvier."], "answer": 2, "two": true, "explain": "<b>en</b> + mes, y el mes con minúscula: nous sommes <b>en janvier</b>."}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-08', 1, 'choice', 'Gramática', $j${"title": "Completa la frase", "fr": "Je suis né ___ Mexique.", "es": "Nací en México.", "options": ["à", "en", "au", "aux"], "answer": 2, "two": true, "explain": "<b>le Mexique</b> es masculino: <b>au</b> Mexique. Con un país femenino: en (en France)."}$j$, 'draft'),
  ('a1-08', 2, 'type', 'Vocabulario', $j${"title": "Escribe la fecha: 1 de enero", "before": "Je suis né le", "after": "janvier.", "answers": ["premier", "1er"], "explain": "El día 1 se dice <b>le premier</b> (1er), no «le un». Los otros días: le deux, le trois…"}$j$, 'draft'),
  ('a1-08', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha a Andrés", "audio": "Je m’appelle Andrés. Je suis né le douze septembre mille neuf cent quatre-vingt-dix-huit, à Cali, en Colombie.", "question": "¿Cuándo nació Andrés?", "options": ["El 2 de septiembre", "El 12 de diciembre", "El 20 de septiembre", "El 12 de septiembre"], "answer": 3, "two": true, "explain": "« Je suis né le <b>douze septembre</b>… » → el 12 de septiembre de 1998."}$j$, 'draft'),
  ('a1-08', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "Él nació en Lima, Perú.", "tiles": ["au", "Pérou.", "né", "Il", "en", "Lima,", "est", "à", "a"], "answer": ["Il", "est", "né", "à", "Lima,", "au", "Pérou."], "explain": "<b>à</b> + ciudad (à Lima), <b>au</b> + país masculino (au Pérou). Y se dice <b>il est né</b>, con être."}$j$, 'draft'),
  ('a1-08', 5, 'match', 'Vocabulario', $j${"title": "Une cada fecha con su forma escrita", "pairs": [["01/01", "le premier janvier"], ["03/05", "le 3 mai"], ["14/02", "le 14 février"], ["21/06", "le 21 juin"], ["12/08", "le 12 août"], ["25/12", "le 25 décembre"]], "explain": "Fecha: <b>le</b> + número + mes. El día 1: le <b>premier</b>."}$j$, 'draft'),
  ('a1-08', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Elle est née le premier mai.", "answers": ["Elle est née le premier mai.", "Elle est née le 1er mai."], "es": "Ella nació el 1 de mayo.", "explain": "Con <b>elle</b>: elle est <b>née</b> (con e final). El día 1 = le <b>premier</b>."}$j$, 'draft'),
  ('a1-08', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Je", "suis", "né", "en", "Paris."], "wrong": 3, "fix": "à", "explain": "Con una ciudad se usa <b>à</b>: je suis né <b>à</b> Paris. «en» es para países femeninos: en France."}$j$, 'draft'),
  ('a1-08', 8, 'choice', 'Situaciones', $j${"title": "En un formulario lees «Date de naissance». ¿Qué escribes?", "options": ["Montréal, Canada", "le 5 mars 1995", "Marie Dubois", "célibataire"], "answer": 1, "two": true, "explain": "<b>date de naissance</b> = fecha de nacimiento. El lugar es el <b>lieu de naissance</b>."}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-09', 1, 'choice', 'Vocabulario', $j${"title": "¿Cómo se dice 10:30?", "options": ["Il est dix heures et quart.", "Il est dix heures et demie.", "Il est dix heures moins le quart.", "Il est demi dix heures."], "answer": 1, "explain": "y media = <b>et demie</b>. y cuarto = et quart. menos cuarto = moins le quart."}$j$, 'draft'),
  ('a1-09', 2, 'type', 'Vocabulario', $j${"title": "Escribe la hora: 12:00 (mediodía)", "before": "À", "after": ", je mange avec mes collègues.", "answers": ["midi"], "explain": "12:00 = <b>midi</b> (mediodía). 0:00 = minuit (medianoche)."}$j$, 'draft'),
  ('a1-09', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha el horario", "audio": "Le cours de français commence le mardi, à six heures et quart. Il finit à huit heures.", "question": "¿A qué hora empieza la clase?", "options": ["A las 6:15", "A las 6:45", "A las 6:30", "A las 8:00"], "answer": 0, "two": true, "explain": "« à six heures <b>et quart</b> » → a las 6:15. La clase termina a las 8."}$j$, 'draft'),
  ('a1-09', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "¿Qué hora es?", "tiles": ["heure", "est-il ?", "Quel", "Quelle", "heures"], "answer": ["Quelle", "heure", "est-il ?"], "explain": "<b>heure</b> es femenino: <b>Quelle</b> heure est-il ?"}$j$, 'draft'),
  ('a1-09', 5, 'match', 'Vocabulario', $j${"title": "Une cada hora con su forma en letras", "pairs": [["8 h 15", "huit heures et quart"], ["8 h 30", "huit heures et demie"], ["7 h 45", "huit heures moins le quart"], ["12 h 00", "midi"], ["0 h 00", "minuit"], ["1 h 00", "une heure"]], "explain": "7:45 = <b>huit heures moins le quart</b>: en francés se dice «8 menos cuarto»."}$j$, 'draft'),
  ('a1-09', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Il est neuf heures et demie.", "answers": ["Il est neuf heures et demie.", "Il est 9 h 30.", "Il est 9h30."], "es": "Son las nueve y media.", "explain": "<b>et demie</b> = y media. heure es femenino: demi<b>e</b>."}$j$, 'draft'),
  ('a1-09', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Mon", "rendez-vous", "est", "à", "une", "heures."], "wrong": 5, "fix": "heure", "explain": "Con <b>une</b>, heure va en singular: une <b>heure</b>. Desde 2: deux heures."}$j$, 'draft'),
  ('a1-09', 8, 'choice', 'Vocabulario', $j${"title": "Son las 15:00. ¿Qué momento del día es?", "options": ["le matin", "la nuit", "le soir", "l’après-midi"], "answer": 3, "two": true, "explain": "15:00 es <b>l’après-midi</b> (la tarde). Le matin = la mañana, le soir = la noche."}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-10', 1, 'choice', 'Gramática', $j${"title": "Completa la frase", "fr": "J’habite ___ Canada.", "es": "Vivo en Canadá.", "options": ["au", "en", "aux", "à"], "answer": 0, "two": true, "explain": "<b>le Canada</b> es masculino: <b>au</b> Canada. Con un país femenino: en (en France)."}$j$, 'draft'),
  ('a1-10', 2, 'type', 'Gramática', $j${"title": "Completa con en, au o aux", "before": "Je vais", "after": "États-Unis.", "answers": ["aux"], "explain": "<b>les États-Unis</b> es plural: <b>aux</b> États-Unis."}$j$, 'draft'),
  ('a1-10', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha a Diego", "audio": "Je m’appelle Diego. Je viens du Mexique. Ma sœur habite en Espagne. Cette année, je vais au Canada.", "question": "¿De dónde viene Diego?", "options": ["De España", "De Canadá", "De México", "De Colombia"], "answer": 2, "two": true, "explain": "« Je viens <b>du Mexique</b>. » Su hermana vive en España y él va a Canadá."}$j$, 'draft'),
  ('a1-10', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "Vengo de Colombia.", "tiles": ["du", "Colombie.", "viens", "Je", "de", "en"], "answer": ["Je", "viens", "de", "Colombie."], "explain": "Origen con un país femenino: <b>de</b> (de Colombie, de France). Con uno masculino: du (du Pérou)."}$j$, 'draft'),
  ('a1-10', 5, 'match', 'Gramática', $j${"title": "Une cada país con «en», «au» o «aux»", "pairs": [["la France", "en France"], ["le Mexique", "au Mexique"], ["les États-Unis", "aux États-Unis"], ["l’Espagne", "en Espagne"], ["le Pérou", "au Pérou"], ["le Canada", "au Canada"]], "explain": "Femenino → <b>en</b>. Masculino → <b>au</b>. Plural → <b>aux</b>."}$j$, 'draft'),
  ('a1-10', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Ma famille habite au Chili.", "answers": ["Ma famille habite au Chili."], "es": "Mi familia vive en Chile.", "explain": "<b>le Chili</b> es masculino: <b>au</b> Chili."}$j$, 'draft'),
  ('a1-10', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Ma", "sœur", "travaille", "au", "France."], "wrong": 3, "fix": "en", "explain": "<b>la France</b> es femenino: <b>en</b> France. «au» es para países masculinos."}$j$, 'draft'),
  ('a1-10', 8, 'choice', 'Vocabulario', $j${"title": "¿Cuál de estos países es femenino?", "options": ["Mexique", "Canada", "Pérou", "Colombie"], "answer": 3, "two": true, "explain": "<b>la Colombie</b> es femenino. Ojo: le Mexique termina en -e pero es masculino."}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-11', 1, 'choice', 'Gramática', $j${"title": "Completa la frase", "fr": "Ana est ___.", "es": "Ana es colombiana.", "options": ["colombienne", "colombien", "colombiens", "colombiene"], "answer": 0, "two": true, "explain": "-ien → <b>-ienne</b> en femenino, con doble n: colombien → colombi<b>enne</b>."}$j$, 'draft'),
  ('a1-11', 2, 'type', 'Vocabulario', $j${"title": "Escribe la nacionalidad", "before": "Elle vient du Mexique : elle est", "after": ".", "answers": ["mexicaine"], "explain": "Femenino: + <b>e</b>. mexicain → mexicain<b>e</b>."}$j$, 'draft'),
  ('a1-11', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha la presentación", "audio": "Au travail, j’ai trois collègues. Kenji est japonais. Amina est marocaine. Et Julie est canadienne.", "question": "¿Quién es canadiense?", "options": ["Kenji", "Amina", "Nadie", "Julie"], "answer": 3, "two": true, "explain": "« Julie est <b>canadienne</b>. » Kenji es japonés y Amina es marroquí."}$j$, 'draft'),
  ('a1-11', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "Ellos son españoles.", "tiles": ["espagnoles.", "sont", "Ils", "espagnols.", "ont"], "answer": ["Ils", "sont", "espagnols."], "explain": "Masculino plural: + <b>s</b> → espagnol<b>s</b>. espagnoles es femenino plural."}$j$, 'draft'),
  ('a1-11', 5, 'match', 'Vocabulario', $j${"title": "Une cada país con la nacionalidad (femenino)", "pairs": [["la France", "française"], ["le Mexique", "mexicaine"], ["l’Italie", "italienne"], ["l’Espagne", "espagnole"], ["la Colombie", "colombienne"], ["le Canada", "canadienne"]], "explain": "La nacionalidad se escribe con <b>minúscula</b>: elle est française."}$j$, 'draft'),
  ('a1-11', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Elles sont mexicaines.", "answers": ["Elles sont mexicaines."], "es": "Ellas son mexicanas.", "explain": "Femenino plural: mexicain + <b>e</b> + <b>s</b> → mexicain<b>es</b>."}$j$, 'draft'),
  ('a1-11', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Maria", "est", "mexicain", "et", "elle", "habite", "à", "Toronto."], "wrong": 2, "fix": "mexicaine", "explain": "Maria es mujer: <b>mexicaine</b>, con e final."}$j$, 'draft'),
  ('a1-11', 8, 'choice', 'Gramática', $j${"title": "¿Qué frase es correcta?", "options": ["Il est Italien.", "Il est italienne.", "Il est itallien.", "Il est italien."], "answer": 3, "two": true, "explain": "Masculino: <b>italien</b>, con minúscula y una sola l."}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-12', 1, 'choice', 'Gramática', $j${"title": "Completa la frase", "fr": "J’habite ___ 25, rue Saint-Denis.", "es": "Vivo en el 25 de la calle Saint-Denis.", "options": ["à", "dans", "au", "en"], "answer": 2, "two": true, "explain": "Antes del número: <b>au</b>. J’habite au 25, rue Saint-Denis."}$j$, 'draft'),
  ('a1-12', 2, 'type', 'Gramática', $j${"title": "Completa con la preposición", "before": "J’habite", "after": "un appartement.", "answers": ["dans"], "explain": "Para el tipo de vivienda: <b>dans</b> un appartement, dans une maison."}$j$, 'draft'),
  ('a1-12', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha a Hugo", "audio": "Bonjour, je m’appelle Hugo. J’habite au dix-huit, rue Laurier, à Gatineau. J’habite dans un studio.", "question": "¿En qué número vive Hugo?", "options": ["18", "8", "80", "28"], "answer": 0, "two": true, "explain": "« J’habite au <b>dix-huit</b>, rue Laurier. » → número 18."}$j$, 'draft'),
  ('a1-12', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "Vivo en el 12 de la calle Laval, en Quebec.", "tiles": ["rue", "à", "Québec.", "au", "Laval,", "J’habite", "12,", "dans"], "answer": ["J’habite", "au", "12,", "rue", "Laval,", "à", "Québec."], "explain": "Orden: <b>au</b> + número, <b>rue</b> + nombre, <b>à</b> + ciudad."}$j$, 'draft'),
  ('a1-12', 5, 'match', 'Vocabulario', $j${"title": "Une cada palabra con su traducción", "pairs": [["l’adresse", "la dirección"], ["la rue", "la calle"], ["le numéro", "el número"], ["le code postal", "el código postal"], ["une maison", "una casa"], ["un appartement", "un apartamento"]], "explain": "En un formulario: <b>adresse</b>, <b>code postal</b>, <b>ville</b>."}$j$, 'draft'),
  ('a1-12', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Quelle est ton adresse ?", "answers": ["Quelle est ton adresse ?"], "es": "¿Cuál es tu dirección?", "explain": "<b>adresse</b> es femenino: quell<b>e</b>. Pero delante de vocal se dice <b>ton</b> adresse. Se escribe con una sola d: adresse."}$j$, 'draft'),
  ('a1-12', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Nous", "habitons", "à", "8,", "rue", "Hugo."], "wrong": 2, "fix": "au", "explain": "Antes del número se usa <b>au</b>: nous habitons <b>au</b> 8, rue Hugo."}$j$, 'draft'),
  ('a1-12', 8, 'choice', 'Situaciones', $j${"title": "Un formulario pide tu dirección. ¿Qué orden es correcto?", "options": ["Montréal, rue Sainte-Catherine, 45", "45, rue Sainte-Catherine, Montréal", "rue 45, Sainte-Catherine, Montréal", "Sainte-Catherine 45 rue, Montréal"], "answer": 1, "explain": "Primero el <b>número</b>, después la <b>calle</b> y al final la <b>ciudad</b>."}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-13', 1, 'choice', 'Vocabulario', $j${"title": "Completa la frase", "fr": "Elle est ___.", "es": "Ella está divorciada.", "options": ["divorcé", "divorcés", "divorcée", "divorce"], "answer": 2, "two": true, "explain": "Femenino: + <b>e</b> → divorcé<b>e</b>. Se pronuncia igual que divorcé."}$j$, 'draft'),
  ('a1-13', 2, 'type', 'Vocabulario', $j${"title": "Escribe el femenino", "before": "Il est veuf. Elle est", "after": ".", "answers": ["veuve"], "explain": "veuf → <b>veuve</b> (viudo → viuda): la f cambia a v."}$j$, 'draft'),
  ('a1-13', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha a Rosa", "audio": "Bonjour, je m’appelle Rosa. Je suis divorcée et j’ai deux enfants. Mon frère est célibataire.", "question": "¿Cuál es la situación de Rosa?", "options": ["Casada", "Soltera", "Divorciada", "Viuda"], "answer": 2, "two": true, "explain": "« Je suis <b>divorcée</b>. » Su hermano es soltero."}$j$, 'draft'),
  ('a1-13', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "Mis padres están casados.", "tiles": ["mariés.", "ont", "parents", "Mes", "sont", "marié."], "answer": ["Mes", "parents", "sont", "mariés."], "explain": "El estado civil va con <b>être</b>: ils <b>sont</b> mariés. Plural: + <b>s</b>."}$j$, 'draft'),
  ('a1-13', 5, 'match', 'Vocabulario', $j${"title": "Une cada palabra con su traducción", "pairs": [["célibataire", "soltero / soltera"], ["marié", "casado"], ["divorcée", "divorciada"], ["veuve", "viuda"], ["un mari", "un esposo"], ["une femme", "una esposa"]], "explain": "<b>célibataire</b> es igual en masculino y femenino."}$j$, 'draft'),
  ('a1-13', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Elle n’est pas mariée.", "answers": ["Elle n’est pas mariée."], "es": "Ella no está casada.", "explain": "Negación: <b>n’</b>est <b>pas</b>. Con elle: marié<b>e</b>."}$j$, 'draft'),
  ('a1-13', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Ma", "mère", "est", "veuf", "depuis", "deux", "ans."], "wrong": 3, "fix": "veuve", "explain": "Para una mujer: <b>veuve</b>. veuf es el masculino."}$j$, 'draft'),
  ('a1-13', 8, 'choice', 'Situaciones', $j${"title": "En un formulario lees «Situation de famille». ¿Qué respuesta va ahí?", "options": ["mariée", "colombienne", "infirmière", "Montréal"], "answer": 0, "two": true, "explain": "<b>situation de famille</b> = estado civil: célibataire, marié(e), divorcé(e), veuf / veuve."}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-14', 1, 'choice', 'Vocabulario', $j${"title": "Completa la frase", "fr": "Elle travaille dans un restaurant : elle est ___.", "es": "Trabaja en un restaurante: es mesera.", "options": ["serveur", "vendeuse", "serveuse", "infirmière"], "answer": 2, "two": true, "explain": "-eur → <b>-euse</b> en femenino: serveur → serv<b>euse</b>."}$j$, 'draft'),
  ('a1-14', 2, 'type', 'Vocabulario', $j${"title": "Escribe el femenino del oficio", "before": "Il est cuisinier. Elle est", "after": ".", "answers": ["cuisinière"], "explain": "-ier → <b>-ière</b>: cuisinier → cuisini<b>ère</b>, con acento grave."}$j$, 'draft'),
  ('a1-14', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha a Omar", "audio": "Bonjour ! Je m’appelle Omar. Je suis infirmier dans un hôpital, à Sherbrooke. Ma femme est professeure. Elle travaille dans une école.", "question": "¿Dónde trabaja la esposa de Omar?", "options": ["En un hospital", "En una escuela", "En un restaurante", "En una tienda"], "answer": 1, "two": true, "explain": "« Ma femme est <b>professeure</b>. Elle travaille dans une <b>école</b>. » Omar trabaja en un hospital."}$j$, 'draft'),
  ('a1-14', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "Soy enfermera.", "tiles": ["une", "infirmière.", "Je", "infirmier.", "suis"], "answer": ["Je", "suis", "infirmière."], "explain": "Para decir tu oficio: <b>je suis</b> + oficio, sin artículo. Femenino de infirmier: infirm<b>ière</b>."}$j$, 'draft'),
  ('a1-14', 5, 'match', 'Vocabulario', $j${"title": "Une cada oficio con su lugar de trabajo", "pairs": [["professeur", "une école"], ["médecin", "un hôpital"], ["cuisinier", "un restaurant"], ["vendeur", "un magasin"], ["boulanger", "une boulangerie"], ["étudiant", "l’université"]], "explain": "Para preguntar: «Tu travailles où ?» → Je travaille dans un magasin."}$j$, 'draft'),
  ('a1-14', 6, 'dictation', 'Dictado', $j${"title": "Escribe lo que oyes", "audio": "Elle est vendeuse dans un magasin.", "answers": ["Elle est vendeuse dans un magasin."], "es": "Ella es vendedora en una tienda.", "explain": "Femenino de vendeur: vend<b>euse</b>. Sin artículo: elle est vendeuse."}$j$, 'draft'),
  ('a1-14', 7, 'spot', 'Detecta el error', $j${"title": "Toca la palabra incorrecta", "words": ["Elle", "est", "étudiant", "à", "l’université."], "wrong": 2, "fix": "étudiante", "explain": "Para una mujer: <b>étudiante</b>, con e final (la t se pronuncia)."}$j$, 'draft'),
  ('a1-14', 8, 'choice', 'Gramática', $j${"title": "¿Qué frase es correcta?", "options": ["Il est médecin.", "Il est un médecin.", "Il est médecine.", "Il a médecin."], "answer": 0, "two": true, "explain": "Para decir la profesión: <b>il est médecin</b>, sin artículo. médecine es la ciencia (la medicina)."}$j$, 'draft');
insert into public.exercises (unit_id, position, type, kind, payload, status) values
  ('a1-15', 1, 'choice', 'Gramática', $j${"title": "Completa la frase", "fr": "___ parents habitent au Pérou.", "es": "Mis padres viven en Perú.", "options": ["Mon", "Ma", "Moi", "Mes"], "answer": 3, "two": true, "explain": "Con un plural se usa <b>mes</b>: mes parents, mes frères."}$j$, 'draft'),
  ('a1-15', 2, 'type', 'Vocabulario', $j${"title": "¿Quién es?", "before": "La mère de ma mère est ma", "after": ".", "answers": ["grand-mère"], "explain": "La madre de tu madre es tu <b>grand-mère</b> (abuela), con guion."}$j$, 'draft'),
  ('a1-15', 3, 'listen', 'Comprensión oral', $j${"title": "Escucha la presentación", "audio": "Voici ma famille. Mon père s’appelle Jorge et ma mère s’appelle Elena. J’ai deux frères et une sœur. Mes grands-parents habitent à Quito.", "question": "¿Dónde viven sus abuelos?", "options": ["En Lima", "En Quito", "En Montreal", "Con sus padres"], "answer": 1, "two": true, "explain": "« Mes <b>grands-parents</b> habitent à <b>Quito</b>. »"}$j$, 'draft'),
  ('a1-15', 4, 'order', 'Construcción', $j${"title": "Ordena la frase", "es": "Mi hermana tiene un hijo.", "tiles": ["fils.", "Mon", "a", "sœur", "un", "Ma", "fille."], "answer": ["Ma", "sœur", "a", "un", "fils."], "explain": "<b>sœur</b> es femenino: <b>ma</b> sœur. <b>le fils</b> = el hijo; la fille = la hija."}$j$, 'draft'),
  ('a1-15', 5, 'match', 'Vocabulario', $j${"title": "Une cada palabra con su traducción", "pairs": [["le père", "el padre"], ["la mère", "la madre"], ["le frère", "el hermano"], ["la sœur", "la hermana"], ["le fils", "el hijo"], ["la fille", "la hija"], ["l’oncle", "el tío"], ["la tante", "la tía"]], "explain": "En <b>fils</b> se pronuncia la s final: [fis]."}$j$, 'draft'),
